CREATE TABLE IF NOT EXISTS enterprise_settings (setting_key TEXT PRIMARY KEY,setting_value TEXT NOT NULL,updated_by TEXT NOT NULL REFERENCES users(id),updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS enterprise_settings_audit (id TEXT PRIMARY KEY,setting_key TEXT NOT NULL,old_value TEXT,new_value TEXT NOT NULL,actor_id TEXT NOT NULL REFERENCES users(id),changed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS enterprise_workflow_options (id TEXT PRIMARY KEY,section TEXT NOT NULL CHECK(section IN ('technical','financial')),kind TEXT NOT NULL CHECK(kind IN ('type','status')),code TEXT NOT NULL,label TEXT NOT NULL,sort_order INTEGER NOT NULL DEFAULT 100,enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)),updated_by TEXT NOT NULL REFERENCES users(id),UNIQUE(section,kind,code));
CREATE TABLE IF NOT EXISTS enterprise_departments (id TEXT PRIMARY KEY,name TEXT NOT NULL,country_code TEXT NOT NULL CHECK(country_code IN ('MU','MG','RW','BI')),manager_id TEXT REFERENCES users(id),active INTEGER NOT NULL DEFAULT 1,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(name,country_code));
CREATE INDEX IF NOT EXISTS idx_enterprise_workflows ON enterprise_workflow_options(section,kind,enabled,sort_order);